//! Generated-file detection: by filename convention, by a generation banner in
//! the file header, or by minified content. Generated files are indexed but
//! ranked below hand-written code.

use regex::Regex;
use std::sync::LazyLock;

static GENERATED_NAME: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(
        r"(?:\.pb\.go|\.pulsar\.go|_grpc\.pb\.go|_mocks?\.go|(?:^|/)mock_[^/]+\.go|\.generated\.[jt]sx?|\.gen\.[jt]sx?|\.pb\.[jt]s|_pb\.[jt]s|_grpc_pb\.[jt]s|[.-]min\.m?js|_pb2(?:_grpc)?\.py|_pb2\.pyi|\.pb\.(?:cc|h)|\.g\.cs|Grpc\.cs|OuterClass\.java|Grpc\.java|\.pb\.swift|\.g\.dart|\.freezed\.dart|\.pb\.dart|\.pbgrpc\.dart|\.chopper\.dart|\.generated\.rs)$",
    )
    .unwrap()
});

const HEADER_SCAN_CHARS: usize = 8192;
const HEADER_SCAN_LINES: usize = 60;

static COMMENT_LEADER: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(r#"(?i)^\s*(?://|/\*+|\*+/?|#+|--+|<!--|%+|;+|'|!|\(\*|\{-|"""|'''|=begin|<#|@rem\b|rem\b)"#).unwrap()
});

static GENERATED_CONTENT: LazyLock<Vec<Regex>> = LazyLock::new(|| {
    [
        r"(?i)\bcode generated\b.{0,200}?\bdo not edit\b",
        r"(?i)\b(?:automatically |auto[- ]?)?generated (?:by|from|with)\b.{0,200}?\bdo not (?:edit|modify|change)\b",
        r"(?:^|[^\p{L}\p{N}_@])@generated\b",
        r"(?i)<auto-?generated\s*/?>",
        r"(?i)\b(?:automatically generated|auto[- ]?generated|autogenerated) by\b",
        r"(?i)\bgenerated by\s+\S.{0,80}?\bby running\b",
        r"(?i)\bthis (?:file|class|code|module) (?:is|was) (?:auto[- ]?)?generated\b",
        r"(?i)\bdo not (?:edit|modify)\b.{0,120}?\b(?:auto[- ]?generated|generated file|generated code)\b",
    ]
    .iter()
    .map(|p| Regex::new(p).unwrap())
    .collect()
});

const BLOCK_DELIMS: &[(&str, &str)] = &[
    ("/*", "*/"),
    ("<!--", "-->"),
    ("\"\"\"", "\"\"\""),
    ("'''", "'''"),
    ("=begin", "=end"),
    ("<#", "#>"),
];

pub fn is_generated_path(path: &str) -> bool {
    GENERATED_NAME.is_match(path)
}

/// A generation banner in a comment within the first lines of the file.
pub fn has_generated_header(content: &str) -> bool {
    let mut end = content.len().min(HEADER_SCAN_CHARS);
    while !content.is_char_boundary(end) {
        end -= 1;
    }
    let head = &content[..end];
    if !head.to_ascii_lowercase().contains("generat") {
        return false;
    }
    let mut open: Option<(&str, &str)> = None;
    for line in head.lines().take(HEADER_SCAN_LINES) {
        if (open.is_some() || COMMENT_LEADER.is_match(line))
            && GENERATED_CONTENT.iter().any(|p| p.is_match(line))
        {
            return true;
        }
        if let Some((_, close)) = open {
            if line.contains(close) {
                open = None;
            }
            continue;
        }
        for &(o, c) in BLOCK_DELIMS {
            if let Some(at) = line.find(o) {
                if !line[at + o.len()..].contains(c) {
                    open = Some((o, c));
                }
                break;
            }
        }
    }
    false
}

/// A bundled/minified script: most of the bytes on very long, punctuation-dense lines.
pub fn is_minified(path: &str, content: &str) -> bool {
    const LONG: usize = 1000;
    let lower = path.to_ascii_lowercase();
    if !(lower.ends_with(".js") || lower.ends_with(".mjs") || lower.ends_with(".cjs"))
        || content.len() < 4 * LONG
    {
        return false;
    }
    if content.contains("function __webpack_require__") {
        return true;
    }
    let (mut long, mut punct) = (0usize, 0usize);
    for line in content.split('\n') {
        if line.len() >= LONG {
            long += line.len();
            punct += line
                .bytes()
                .filter(|b| matches!(b, b';' | b'{' | b'}' | b'(' | b')' | b','))
                .count();
        }
    }
    long * 2 >= content.len() && punct as f64 >= long as f64 * 0.03
}

pub fn is_generated(path: &str, content: &str) -> bool {
    is_generated_path(path) || has_generated_header(content) || is_minified(path, content)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn detects_generated_files() {
        assert!(is_generated_path("api/x.pb.go"));
        assert!(is_generated_path("lib/a.g.dart"));
        assert!(!is_generated_path("src/a.ts"));
        assert!(has_generated_header(
            "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x"
        ));
        assert!(has_generated_header(
            "/*\n * This file was automatically generated by foo\n */"
        ));
        assert!(!has_generated_header(
            "// generates the report\nfn main() {}"
        ));
    }
}
